function parse(value){check(typeof value==='string'&&value.length<=MAX_BYTES&&new TextEncoder().encode(value).length<=MAX_BYTES,'Файл больше 8 МБ');const raw=value.trim().replace(/^```(?:json)?\s*([\s\S]*?)\s*```$/i,'$1');return validate(JSON.parse(raw));}
