function defaultDriver(row,targetUnit){if(row.type==='resource'&&known(row.entity.quantity))return 'resource_quantity';if(row.type!=='part')return 'measure';return ({м:'part_length',м2:'face_area',м3:'volume',кг:'mass',шт:'count'}[unit(targetUnit)]||'count');}
